    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers)
        group.MapGet("/", [Authorize] async (ShipmentDbContext db) =>
        {
            return await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .ToListAsync();
        });

        // Get shipment by tracking number (customers)
        group.MapGet("/track/{trackingNumber}", [Authorize] async (string trackingNumber, ShipmentDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        // Create a new shipment (dispatchers)
        group.MapPost("/", [Authorize] async (Shipment shipment, ShipmentDbContext db) =>
        {
            shipment.CreatedAt = DateTime.UtcNow;
            shipment.TrackingNumber = GenerateTrackingNumber();
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", shipment);
        });

        // Update shipment status (dispatchers)
        group.MapPut("/{id:int}/status", [Authorize] async (int id, ShipmentStatusUpdate update, ShipmentDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = update.Status;
            if (update.EstimatedDelivery.HasValue)
                shipment.EstimatedDelivery = update.EstimatedDelivery;

            await db.SaveChangesAsync();
            return Results.Ok(shipment);
        });
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

public record ShipmentStatusUpdate(ShipmentStatus Status, DateTime? EstimatedDelivery);

